#include <iostream>
#include <string>
using namespace std;

struct Guard {
    string name;
    Guard(string n) : name(n) { cout << "领到 " << name << endl; }
    ~Guard() { cout << "还回 " << name << endl; }
};

void work() {
    Guard g("{goods}");
    throw string("半路出事");
}

int main() {
    try {
        work();
    } catch (string e) {
        cout << "接住：" << e << endl;
    }
    return 0;
}
